    print('=====',f)
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_') and any(k in l for k in ['title','source','characteristics','treatment','description','geo_acc']):
            print(l[:1500].rstrip())

import gzip,glob,pandas as pd
pd.set_option('display.width',300); pd.set_option('display.max_colwidth',120); pd.set_option('display.max_rows',500)
def meta(f):
    rows={}
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'):
            p=l.rstrip('\n').split('\t'); k=p[0]
            while k in rows: k+='_'
            rows[k]=[x.strip('"') for x in p[1:]]
        elif l.startswith('!Series_'): 
            if any(s in l for s in ['summary','overall_design','title']): print(l[:1500])
    return pd.DataFrame(rows)
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    print('=====',f); d=meta(f)
    for c in d.columns:
        if d[c].nunique()>1 and not any(s in c for s in ['supplementary','geo_acc','date','contact','relation','data_row']):
            print(c, d[c].value_counts().to_dict() if d[c].nunique()<40 else d[c].nunique())

